<?php
declare(strict_types=1);
namespace MVO\Tests;
use PHPUnit\Framework\TestCase;
use MVO\Message\MessageCodec;
use MVO\Protocol\{BinaryNode,SchemaCodec};
use MVO\Voip\{GroupCallState,GroupMediaSession,RelayTransport,VoipService};

final class VoipSignalingTest extends TestCase
{
    private float $now=1000.0;private array $queries=[];private array $sent=[];private array $attempts=[];private array $events=[];private array $resolved=[];private array $encrypted=[];private array $callKeys=[];private array $legs=[];private array $failures=[];private bool $insideHandler=false;private bool $autoAcknowledge=true;private array $relayNodes=[];
    private function service(string $own):VoipService
    {
        $service=null;
        return $service=new VoipService(static fn()=>['meLid'=>$own],function($node)use($own){self::assertFalse($this->insideHandler,'Incoming signaling queried recursively');$this->queries[$own][]=$node;return new BinaryNode('ack',['class'=>'call','id'=>$node->attrs['id']],$this->relayNodes);},function($node)use($own,&$service){$this->attempts[$own][]=$node;$tag=is_array($node->content)?($node->content[0]->tag??$node->tag):$node->tag;if(($this->failures[$tag]??0)!==0){if($this->failures[$tag]>0)--$this->failures[$tag];throw new \RuntimeException('Synthetic send failure');}$this->sent[$own][]=$node;if($node->tag==='call' && $this->autoAcknowledge)$service->handleNode(new BinaryNode('ack',['class'=>'call','type'=>$tag,'id'=>$node->attrs['id']]));},function($peer)use($own){self::assertFalse($this->insideHandler,'Incoming signaling resolved devices recursively');$this->resolved[$own]=($this->resolved[$own]??0)+1;return $peer==='111@lid'?['111:1@lid','111:2@lid']:['222:1@lid','222:2@lid'];},function($devices,$padded)use($own){self::assertFalse($this->insideHandler,'Incoming signaling encrypted a rekey recursively');$this->encrypted[$own]=($this->encrypted[$own]??0)+1;$this->callKeys[$own]=SchemaCodec::decode('Message',MessageCodec::unpad($padded))['call']['callKey'];$nodes=[];foreach($devices as $device)$nodes[]=new BinaryNode('to',['jid'=>$device],[new BinaryNode('enc',['type'=>'msg'],$padded)]);return ['nodes'=>$nodes,'deviceIdentity'=>null];},static fn($from,$type,$cipher)=>$cipher,function($event,$data)use($own){$this->events[$own][]=['event'=>$event,'data'=>$data];},fn()=>$this->now,function($descriptor){return $this->legs[]=new VoipSignalingRelay();});
    }
    private function incoming(VoipService $service,BinaryNode $node):void { $this->insideHandler=true;try{$service->handleNode($node);}finally{$this->insideHandler=false;} }
    private static function from(BinaryNode $node,string $from):BinaryNode { return new BinaryNode('call',['from'=>$from,'id'=>$node->attrs['id']],$node->content); }
    private function tagged(string $own,string $tag):array { return array_values(array_filter($this->sent[$own]??[],static fn($node)=>$node->child($tag)!==null)); }
    private static function info(int $epoch,array $devices=['111:1@lid','222:1@lid'],bool $rekey=false):BinaryNode { $users=[];foreach($devices as $i=>$jid)$users[]=new BinaryNode('user',['jid'=>GroupCallState::account($jid),'state'=>'connected'],[new BinaryNode('device',['jid'=>$jid,'pid'=>(string)$i])]);return new BinaryNode('group_info',['media'=>'audio','connected_limit'=>'32','transaction-id'=>(string)$epoch,...($rekey?['rekey'=>'1']:[])],$users); }
    private function group(VoipService $service,string $id='GROUP'):void { $this->incoming($service,new BinaryNode('call',['from'=>$id.'@call','id'=>'OFFER'],[new BinaryNode('offer',['call-id'=>$id,'call-creator'=>'111:1@lid','group-jid'=>'123@g.us'],[self::info(1,rekey:true)])])); }

    public function testPreacceptAndTransportSequenceIsAutomaticDeferredAndDoesNotAcceptOrOpenMedia():void
    {
        $a=$this->service('111:1@lid');$b=$this->service('222:1@lid');$id=$a->offer('222@lid')['callId'];self::assertSame([],$this->sent['111:1@lid']??[]);$offer=$this->queries['111:1@lid'][0];$this->incoming($b,self::from($offer,'111:1@lid'));self::assertSame('ringing',$b->getCall($id)['state']);self::assertSame(0,$this->resolved['222:1@lid']??0);self::assertCount(1,$this->sent['222:1@lid']);$a->tick(false);$b->tick(false);self::assertCount(1,$this->tagged('111:1@lid','preaccept'));self::assertCount(1,$this->tagged('222:1@lid','preaccept'));self::assertSame(0,$this->resolved['222:1@lid']??0);self::assertSame([],$this->legs);self::assertSame('ringing',$b->getCall($id)['state']);
        $this->incoming($a,self::from($this->tagged('222:1@lid','preaccept')[0],'222:1@lid'));self::assertSame([],$this->tagged('111:1@lid','transport'));$a->tick(false);$transport=$this->tagged('111:1@lid','transport')[0];self::assertSame('222@lid',$transport->attrs['to']);self::assertSame('0',$transport->child('transport')->attrs['transport-message-type']);self::assertSame('0',$transport->child('transport')->attrs['p2p-cand-round']);
        $b->accept($id);$out=$this->tagged('222:1@lid','transport')[0];self::assertSame('111:1@lid',$out->attrs['to']);self::assertSame('1',$out->child('transport')->attrs['transport-message-type']);self::assertSame('1',$out->child('transport')->attrs['p2p-cand-round']);$accept=$this->queries['222:1@lid'][0];$this->incoming($a,self::from($accept,'222:1@lid'));$a->tick(false);self::assertCount(2,$this->tagged('111:1@lid','transport'));self::assertSame('222:1@lid',$this->tagged('111:1@lid','transport')[1]->attrs['to']);self::assertCount(1,array_filter($this->sent['111:1@lid'],static fn($node)=>$node->tag==='receipt'));self::assertCount(1,$this->queries['111:1@lid']);self::assertSame(0,$this->resolved['222:1@lid']??0);$b->tick(true);$b->tick(true);self::assertSame(0,$this->resolved['222:1@lid']??0);self::assertSame([],$this->legs);
    }
    public function testGroupHeartbeatAndRekeyRespectTickFalseAndInitialMuteRequiresAuthenticatedMedia():void
    {
        $b=$this->service('222:1@lid');$this->group($b);$b->tick(false);self::assertSame([],$this->tagged('222:1@lid','heartbeat'));self::assertSame('GROUP@call',$this->tagged('222:1@lid','preaccept')[0]->attrs['to']);$b->accept('GROUP');$b->tick(false);self::assertCount(1,$this->tagged('222:1@lid','heartbeat'));self::assertSame(0,$this->encrypted['222:1@lid']??0);self::assertSame(0,$this->resolved['222:1@lid']??0);self::assertCount(1,$this->queries['222:1@lid']);self::assertSame([],$this->tagged('222:1@lid','mute_v2'));$b->tick(true);self::assertSame(1,$this->encrypted['222:1@lid']);$b->tick(true);self::assertSame(1,$this->encrypted['222:1@lid']);
        $state=new GroupCallState('GROUP');$state->applyRoster(self::info(1),'GROUP@call','111:1@lid');$peer=new GroupMediaSession('GROUP','111:1@lid',$state);$peer->rotateKey($this->callKeys['222:1@lid'],1);$b->groupMedia('GROUP')->handleDatagram($peer->protectPayload('opus',160));self::assertSame([],$this->tagged('222:1@lid','mute_v2'));$b->tick(false);self::assertCount(1,$this->tagged('222:1@lid','mute_v2'));self::assertSame('0',$this->tagged('222:1@lid','mute_v2')[0]->child('mute_v2')->attrs['mute-state']);$b->tick(false);self::assertCount(1,$this->tagged('222:1@lid','mute_v2'));$this->now+=10;$b->tick(false);self::assertCount(2,$this->tagged('222:1@lid','heartbeat'));
        $b->setHandRaised('GROUP',true);$this->incoming($b,new BinaryNode('call',['from'=>'GROUP@call','id'=>'ARRIVED'],[new BinaryNode('group_update',['call-id'=>'GROUP','call-creator'=>'111:1@lid'],[self::info(2,['111:1@lid','222:1@lid','333:1@lid'])])]));$b->tick(false);self::assertCount(2,$this->tagged('222:1@lid','mute_v2'));self::assertCount(1,$this->tagged('222:1@lid','user_action'));$b->leave('GROUP');$this->now+=20;$b->tick(false);self::assertCount(2,$this->tagged('222:1@lid','heartbeat'));self::assertSame('ended',$b->getCall('GROUP')['state']);
    }
    public function testSignalRetryUsesSameIdAndStopsAfterThreeFailures():void
    {
        $service=$this->service('111:1@lid');$service->offer('222@lid');$this->failures['preaccept']=-1;$service->tick(false);$service->tick(false);self::assertCount(1,$this->attempts['111:1@lid']);$this->now+=0.5;$service->tick(false);$this->now+=1;$service->tick(false);$this->now+=10;$service->tick(false);self::assertCount(3,$this->attempts['111:1@lid']);self::assertCount(1,array_unique(array_map(static fn($node)=>$node->attrs['id'],$this->attempts['111:1@lid'])));$errors=array_values(array_filter($this->events['111:1@lid'],static fn($event)=>$event['event']==='voip_error'));self::assertFalse($errors[2]['data']['retrying']);self::assertSame([],$this->sent['111:1@lid']??[]);
    }
    public function testDeferredCallAckIsCorrelatedAndNegativeAckRetriesWithoutQueries():void
    {
        $this->autoAcknowledge=false;$service=$this->service('111:1@lid');$id=$service->offer('222@lid')['callId'];$service->tick(false);$node=$this->tagged('111:1@lid','preaccept')[0];$attrs=['class'=>'call','id'=>$node->attrs['id'],'type'=>'preaccept'];self::assertFalse($service->handleNode(new BinaryNode('ack',[...$attrs,'id'=>'unknown'])));self::assertFalse($service->handleNode(new BinaryNode('ack',[...$attrs,'class'=>'receipt'])));self::assertFalse($service->handleNode(new BinaryNode('ack',[...$attrs,'type'=>'transport'])));
        $this->incoming($service,new BinaryNode('ack',[...$attrs,'error'=>'500']));$this->incoming($service,new BinaryNode('ack',$attrs,[new BinaryNode('error',['code'=>'500'])]));self::assertCount(1,$this->tagged('111:1@lid','preaccept'));$service->tick(false);self::assertCount(1,$this->tagged('111:1@lid','preaccept'));$this->now+=0.5;$service->tick(false);self::assertCount(2,$this->tagged('111:1@lid','preaccept'));self::assertSame($node->attrs['id'],$this->tagged('111:1@lid','preaccept')[1]->attrs['id']);
        $this->incoming($service,new BinaryNode('ack',$attrs));self::assertFalse($service->handleNode(new BinaryNode('ack',$attrs)));$this->now+=20;$service->tick(false);self::assertCount(2,$this->tagged('111:1@lid','preaccept'));self::assertCount(1,$this->queries['111:1@lid']);self::assertSame(1,$this->resolved['111:1@lid']);self::assertSame(1,$this->encrypted['111:1@lid']);self::assertSame('offered',$service->getCall($id)['state']);$ackEvents=array_values(array_filter($this->events['111:1@lid'],static fn($event)=>$event['event']==='voip_signaling_ack'));self::assertCount(1,$ackEvents);self::assertSame(['callId'=>$id,'type'=>'preaccept','attempts'=>2],$ackEvents[0]['data']);self::assertCount(1,array_filter($this->events['111:1@lid'],static fn($event)=>$event['event']==='voip_error'));
    }
    public function testMissingCallAckTimesOutAndStopsAfterThreeIdenticalWrites():void
    {
        $this->autoAcknowledge=false;$service=$this->service('111:1@lid');$service->offer('222@lid');foreach([0,3,3.5,6.5,7.5,10.5,20] as $offset){$this->now=1000+$offset;$service->tick(false);}self::assertCount(3,$this->tagged('111:1@lid','preaccept'));$ids=array_unique(array_map(static fn($node)=>$node->attrs['id'],$this->tagged('111:1@lid','preaccept')));self::assertCount(1,$ids);self::assertFalse($service->handleNode(new BinaryNode('ack',['class'=>'call','id'=>$ids[0]])));$errors=array_values(array_filter($this->events['111:1@lid'],static fn($event)=>$event['event']==='voip_error'));self::assertSame([1,2,3],array_column(array_column($errors,'data'),'attempt'));self::assertSame([true,true,false],array_column(array_column($errors,'data'),'retrying'));self::assertSame([],(new \ReflectionProperty(VoipService::class,'signals'))->getValue($service));self::assertSame([],(new \ReflectionProperty(VoipService::class,'signalIds'))->getValue($service));self::assertCount(0,array_filter($this->events['111:1@lid'],static fn($event)=>$event['event']==='voip_signaling_ack'));
    }
    public function testHeartbeatWithoutAckIsCoalescedAndOnlyRetriesThreeTimesPerInterval():void
    {
        $service=$this->service('222:1@lid');$this->group($service);$service->tick(false);$service->accept('GROUP');$this->autoAcknowledge=false;foreach([0,3,3.5,6.5,7.5,10,10.5,11] as $offset){$this->now=1000+$offset;$service->tick(false);self::assertLessThanOrEqual(1,count((new \ReflectionProperty(VoipService::class,'signals'))->getValue($service)));}self::assertCount(3,$this->tagged('222:1@lid','heartbeat'));$ids=array_map(static fn($node)=>$node->attrs['id'],$this->tagged('222:1@lid','heartbeat'));self::assertCount(1,array_unique($ids));self::assertSame([],(new \ReflectionProperty(VoipService::class,'signals'))->getValue($service));self::assertCount(1,$this->queries['222:1@lid']);self::assertSame(0,$this->encrypted['222:1@lid']??0);$this->now=1020;$service->tick(false);self::assertCount(4,$this->tagged('222:1@lid','heartbeat'));self::assertNotSame($ids[0],$this->tagged('222:1@lid','heartbeat')[3]->attrs['id']);$service->leave('GROUP');self::assertSame([],(new \ReflectionProperty(VoipService::class,'signalIds'))->getValue($service));$this->now+=30;$service->tick(false);self::assertCount(4,$this->tagged('222:1@lid','heartbeat'));
    }
    public function testExplicitMuteAndLowerHandCancelOlderUnacknowledgedSnapshots():void
    {
        $service=$this->service('222:1@lid');$this->group($service);$service->tick(false);$service->accept('GROUP');$service->tick(true);$state=new GroupCallState('GROUP');$state->applyRoster(self::info(1),'GROUP@call','111:1@lid');$peer=new GroupMediaSession('GROUP','111:1@lid',$state);$peer->rotateKey($this->callKeys['222:1@lid'],1);$this->autoAcknowledge=false;$service->groupMedia('GROUP')->handleDatagram($peer->protectPayload('opus',160));$service->tick(false);$oldMute=$this->tagged('222:1@lid','mute_v2')[0];self::assertSame('0',$oldMute->child('mute_v2')->attrs['mute-state']);$service->setMuted('GROUP',true);self::assertTrue($service->getCall('GROUP')['audioMuted']);self::assertSame('1',end($this->queries['222:1@lid'])->child('mute_v2')->attrs['mute-state']);self::assertFalse($service->handleNode(new BinaryNode('ack',['class'=>'call','id'=>$oldMute->attrs['id'],'error'=>'500'])));$this->now+=3.5;$service->tick(false);self::assertCount(1,$this->tagged('222:1@lid','mute_v2'));
        $service->setHandRaised('GROUP',true);$this->incoming($service,new BinaryNode('call',['from'=>'GROUP@call','id'=>'ARRIVED'],[new BinaryNode('group_update',['call-id'=>'GROUP','call-creator'=>'111:1@lid'],[self::info(2,['111:1@lid','222:1@lid','333:1@lid'])])]));$service->tick(false);$oldHand=$this->tagged('222:1@lid','user_action')[0];self::assertSame('1',$oldHand->child('user_action')->child('raise_hand')->attrs['raise-hand-state']);$service->setHandRaised('GROUP',false);self::assertFalse($service->getCall('GROUP')['handRaised']);self::assertFalse($service->handleNode(new BinaryNode('ack',['class'=>'call','id'=>$oldHand->attrs['id']])));$this->now+=3;$service->tick(false);$this->now+=0.5;$service->tick(false);self::assertCount(1,$this->tagged('222:1@lid','user_action'));self::assertSame('0',end($this->queries['222:1@lid'])->child('user_action')->child('raise_hand')->attrs['raise-hand-state']);foreach(array_slice($this->tagged('222:1@lid','mute_v2'),1) as $node)self::assertSame('1',$node->child('mute_v2')->attrs['mute-state']);
    }
    public function testRelayLatencyUsesOnlyMeasuredAnswersAndTargetsEveryDevice():void
    {
        $this->relayNodes=[new BinaryNode('user',['jid'=>'111@lid'],[new BinaryNode('device',['jid'=>'111:1@lid'])]),new BinaryNode('relay',[],[new BinaryNode('key',[],str_repeat('k',32)),new BinaryNode('token',['id'=>'0'],'token'),new BinaryNode('te',['token_id'=>'0','relay_name'=>'relay-one'],inet_pton('127.0.0.1').pack('n',5000)),new BinaryNode('te',['token_id'=>'0','relay_name'=>'relay-one'],inet_pton('127.0.0.1').pack('n',5001)),new BinaryNode('te',['token_id'=>'0','relay_name'=>'relay-two'],inet_pton('127.0.0.1').pack('n',5002))])];$service=$this->service('111:1@lid');$id=$service->offer('222@lid')['callId'];$this->incoming($service,new BinaryNode('call',['from'=>'222:2@lid','id'=>'ACCEPT'],[new BinaryNode('accept',['call-id'=>$id,'call-creator'=>'111:1@lid'])]));$service->connectMedia($id);$service->tick(false);self::assertSame([],$this->tagged('111:1@lid','relaylatency'));$this->legs[0]->allocated=true;$this->legs[0]->rtt=12;$this->legs[1]->allocated=true;$this->legs[1]->rtt=5;$this->legs[2]->rtt=7;$service->tick(false);$reports=$this->tagged('111:1@lid','relaylatency');self::assertCount(1,$reports);$body=$reports[0]->child('relaylatency');self::assertSame((string)(0x2000000+5),$body->child('te')->attrs['latency']);self::assertSame('relay-one',$body->child('te')->attrs['relay_name']);self::assertEqualsCanonicalizing(['111:1@lid','222:1@lid','222:2@lid'],array_map(static fn($node)=>$node->attrs['jid'],$body->child('destination')->content));self::assertSame(['te','destination'],array_map(static fn($node)=>$node->tag,$body->content));$service->tick(false);self::assertCount(1,$this->tagged('111:1@lid','relaylatency'));$this->legs[2]->allocated=true;$service->tick(false);self::assertCount(2,$this->tagged('111:1@lid','relaylatency'));
        $this->incoming($service,new BinaryNode('call',['from'=>'222:2@lid','id'=>'DEVICE'],[new BinaryNode('transport',['call-id'=>$id,'call-creator'=>'111:1@lid'],[new BinaryNode('user',['jid'=>'222@lid'],[new BinaryNode('device',['jid'=>'222:3@lid'])])])]));$service->tick(false);$reports=$this->tagged('111:1@lid','relaylatency');self::assertCount(4,$reports);foreach(array_slice($reports,2) as $report)self::assertEqualsCanonicalizing(['111:1@lid','222:1@lid','222:2@lid','222:3@lid'],array_map(static fn($node)=>$node->attrs['jid'],$report->child('relaylatency')->child('destination')->content));$service->tick(false);self::assertCount(4,$this->tagged('111:1@lid','relaylatency'));
    }
}
final class VoipSignalingRelay implements RelayTransport
{
    public bool $allocated=false;public ?int $rtt=null;
    public function connect(array $selfSsrcs,array $peerSsrcs=[]):void {}
    public function send(string $packet):void {}
    public function receive(float $timeout=0.0):?string { return null; }
    public function tick():void {}
    public function close():void {}
    public function reregister():void {}
    public function updateSubscriptions(array $selfSsrcs,array $peerSsrcs,?string $streamDescriptor=null,?string $rxSubscriptions=null):void {}
    public function metrics():array { return ['open'=>true,'allocated'=>$this->allocated,'lastPongAt'=>0.0,'openedAt'=>1000.0,'rttMs'=>$this->rtt]; }
}
